use crate::constants::NO_PROJECT;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities::{format_duration_compact, normalize_time_entry_list_filters};
use std::collections::HashMap;

pub struct StatsCommand;

fn aggregate_by_project(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals = HashMap::<String, i64>::new();

    for entry in entries.iter().filter(|entry| !entry.is_running()) {
        let project_name = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| NO_PROJECT.to_string());
        *totals.entry(project_name).or_default() += entry.duration;
    }

    let mut totals = totals.into_iter().collect::<Vec<_>>();
    totals.sort_by(|(name_a, duration_a), (name_b, duration_b)| {
        duration_b.cmp(duration_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

fn print_stats(entries: &[TimeEntry]) {
    let totals = aggregate_by_project(entries);
    let total_seconds = totals.iter().map(|(_, seconds)| seconds).sum::<i64>();

    for (project_name, seconds) in totals {
        println!("{}  {}", format_duration_compact(seconds), project_name);
    }
    println!("{}  Total", format_duration_compact(total_seconds));
}

impl StatsCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let entries = if since.is_some() || until.is_some() {
            let (since, until) = normalize_time_entry_list_filters(since, until)?;
            api_client.get_time_entries_filtered(since, until).await?
        } else {
            api_client.get_entities().await?.time_entries
        };

        print_stats(&entries);
        Ok(())
    }
}

